# 관심사 채널 글에서 '글로 반복되는 질문' 찾기 (가상 글 6개)
from collections import Counter
posts = [
    "이 동네 어린이집 자리 나는 데 있나요?",
    "어린이집 대기 몇 번째인지 어디서 봐요?",
    "강아지랑 같이 갈 수 있는 식당 어디예요?",
    "어린이집 자리 생기면 알려주는 곳 있나요?",
    "애견 동반 식당 추천해 주세요",
    "주말에 아이랑 갈 만한 곳",
]
topics = {"어린이집 자리": ["어린이집"], "동반 식당": ["강아지", "애견", "동반"]}
count = Counter()
for p in posts:
    for name, words in topics.items():
        if any(w in p for w in words):
            count[name] += 1
for name, n in count.most_common():
    print(f"{name}: {n}/{len(posts)}건")

# 임베딩으로 '비슷한 글' 고르기 — 숫자 3개짜리 가상 벡터(실제는 수백~수천 차원)
import math
def cos(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))
posts = {
    "강아지 동반 식당 추천": [0.9, 0.1, 0.0],
    "애견 카페 다녀왔어요":   [0.8, 0.3, 0.1],
    "어린이집 대기 순번":     [0.0, 0.2, 0.9],
}
query = [0.85, 0.2, 0.05]  # '강아지랑 갈 수 있는 곳'의 벡터라고 치자
for title, v in sorted(posts.items(), key=lambda kv: -cos(query, kv[1])):
    print(f"{cos(query, v):.3f}  {title}")
